window.kbPageData["views/entry/k-15b3148c470f85ea"] = {"key":"entry/k-15b3148c470f85ea","state":{"route":"entry/k-15b3148c470f85ea"},"node":{"id":"k-15b3148c470f85ea","mode":"k","title":"组合数","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["从不同对象中无序选取若干对象的组合数","组合数表示从不同对象中无序选取指定数量的选法数","无序选取的组合数","从n个不同对象中无序选取k个的方案数为组合数C(n,k)","组合数计算从不同元素中无序选取指定数量的选法"],"qs":["国考 2023 地市级 行测#63","国考 2024 副省级 行测#68","国考 2024 地市级 行测#64","国考 2024 行政执法 行测#70","江苏 2024 C类 行测#59"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":4,"repeatPositions":1,"directorySummary":"从n个不同对象中选出k个，选取顺序不影响结果时，选法数为C(n,k)＝n!÷[k!(n－k)!]，其中0≤k≤n。","review":{"definition":"从n个不同对象中选出k个，选取顺序不影响结果时，选法数为C(n,k)＝n!÷[k!(n－k)!]，其中0≤k≤n。","explanation":"第63题每户领一份，确定150元礼包的领取户就确定了整种方案。10份都按100元购买需1000元，每换一份150元礼包多花50元，预算允许换0至5份。换0至3份时从3户孤寡老人中选，分别有1、3、3、1种。换4或5份时先给这3户，再从其余7户中选1户或2户，有7、21种。各类相加得36种。","references":[],"evidence":"优先在3户孤寡老人中选择发放对象","disposition":"独立词条","basis":"据原题和解析编释。","title":"组合数","related":[],"examFocus":{"国考 2023 地市级 行测#63":"根据预算确定高价礼包的份数范围，再按份数分类，用组合数统计符合优先发放条件的领取户选法。","国考 2024 副省级 行测#68":"按甲课题的团队数分类，用组合数统计分组方式，再把每组符合编号限制的负责人选法计入。","国考 2024 行政执法 行测#70":"按甲地接待的批数分类，用组合数从符合条件的批次中选出去甲地的批次，再考虑其余批次怎样分到乙、丙两地且两地都有安排。","江苏 2024 C类 行测#59":"遇到“至少一个”的概率题，可以用组合数分别统计全部选法和一个也未入选的选法。"}},"readings":[{"origin":"k-15b3148c470f85ea","title":"组合数","qs":["国考 2023 地市级 行测#63"],"definition":"从n个不同对象中选出k个，选取顺序不影响结果时，选法数为C(n,k)＝n!÷[k!(n－k)!]，其中0≤k≤n。","explanation":"第63题每户领一份，确定150元礼包的领取户就确定了整种方案。10份都按100元购买需1000元，每换一份150元礼包多花50元，预算允许换0至5份。换0至3份时从3户孤寡老人中选，分别有1、3、3、1种。换4或5份时先给这3户，再从其余7户中选1户或2户，有7、21种。各类相加得36种。","evidence":"优先在3户孤寡老人中选择发放对象","doubt":"","references":[]},{"origin":"k-17243e0375090389","title":"组合数","qs":["国考 2024 副省级 行测#68"],"definition":"组合数 C(n,k) 表示从 n 个不同对象中选出 k 个对象的选法数。只要选出的对象相同，选取顺序不同也算同一种选法。","explanation":"甲、乙是两个指定课题。固定甲课题的团队数后，从 6 个团队中无序选出甲的成员，剩下的团队就归乙。甲有 2、3、4 个团队时，分组数分别为 15、20、15。每组恰好排除编号最小的团队，其余团队都可担任负责人，因此三类分别有 15×1×3、20×2×2、15×3×1 种完整安排，共 170 种，对应 D。","evidence":"甲课题由2个团队参与","doubt":"","references":[]},{"origin":"k-37a943982682b530","title":"组合数","qs":["国考 2024 行政执法 行测#70"],"definition":"组合数是从 n 个不同对象中选出 k 个对象且不计选取顺序的选法总数，记作 C(n,k)。","explanation":"第一、二批不能去甲地，因此甲地接待两批时，只能从第三、第四、第五批中选两批。先选第三批再选第四批与反过来选是同一种安排，所以甲地的批次有 C(3,2)=3 种选法。剩余三批还要分到乙、丙两个可区分的地点，且两地都至少有一批。先确定哪一地只接待一批，再选出这一批，共有 2×3=6 种分法，因此甲地接待两批的情形共有 18 种。","evidence":"先从后三批中选2批去甲地","doubt":"","references":[]},{"origin":"k-6a323eacdb434672","title":"组合数","qs":["江苏 2024 C类 行测#59"],"definition":"从 n 个不同对象中选出 k 个，只按选中的对象区分结果时，选法数为组合数 C(n,k)。","explanation":"本题每种选法由入选的 3 个节目确定，全部选法有 C(8,3)＝56 种。若小张所在科室的 2 个节目均未入选，3 个节目都须从其他科室的 6 个节目中选出，因此有 C(6,3)＝20 种选法。","evidence":"从8个节目中随机选出3个","doubt":"","references":[]},{"origin":"k-c27151ef854c856b","title":"组合数","qs":["国考 2024 地市级 行测#64"],"definition":"从 n 个不同元素中选出 k 个，只按所选元素区分方案时，选法总数称为组合数，记作 C(n,k)。","explanation":"本题确定甲课题的团队集合后，剩余团队便归乙课题。调换同一课题内所选团队的排列顺序仍是同一种分组，所以甲选 2、3、4 队分别有 C(6,2)＝15、C(6,3)＝20、C(6,4)＝15 种。负责团队在分组确定后另行选择。","evidence":"乙课题由剩余的3个团队参与","doubt":"","references":[]}]},"questions":{"国考 2023 地市级 行测#63":{"paper":"国考 2023 地市级 行测","n":63,"mod":"数量关系","src":["64bc3a15d27a04e94940.pdf",11],"asrc":["f3ab652d8e31c5bbdabc.pdf",20],"card":"238ebb9c2a98a86983a005cd","links":[{"id":"k-15b3148c470f85ea","role":"解题依据","why":"同一价位礼包的发放方案由领取户的集合确定，选择顺序不影响方案。"}]},"国考 2024 副省级 行测#68":{"paper":"国考 2024 副省级 行测","n":68,"mod":"数量关系","src":["a566fec37e508ca7f975.pdf",12],"asrc":["a475ecf57d968bc14cd6.pdf",20],"card":"311c91f777916a91e3618691","links":[{"id":"k-15b3148c470f85ea","role":"解题依据","why":"固定甲课题的团队数后，只需选择团队成员，选取顺序不影响分组。"}]},"国考 2024 地市级 行测#64":{"paper":"国考 2024 地市级 行测","n":64,"mod":"数量关系","src":["92d0b72e86a6a33d568d.pdf",11],"asrc":["e1792c53900a45f1b9fa.pdf",19],"card":"20e57347444a693d0bfc4f89","links":[{"id":"k-15b3148c470f85ea","role":"解题依据","why":"选定甲课题的团队集合后，乙课题的团队随之确定，组内顺序不影响分组。"}]},"国考 2024 行政执法 行测#70":{"paper":"国考 2024 行政执法 行测","n":70,"mod":"数量关系","src":["dfddc59dc6e7d9da5d71.pdf",13],"asrc":["6493f3a6a55c38431852.pdf",22],"card":"be6819af79813afbc178f31c","links":[{"id":"k-15b3148c470f85ea","role":"解题依据","why":"选出同去甲地的批次时，选取顺序不影响安排。"}]},"江苏 2024 C类 行测#59":{"paper":"江苏 2024 C类 行测","n":59,"mod":"数量关系","src":["3f1ec77ae8a18519b57e.pdf",10],"asrc":["02d6b49839583bdaf297.pdf",16],"card":"12be07104d0ccb37b68cde80","links":[{"id":"k-15b3148c470f85ea","role":"解题依据","why":"总选法和反面事件的选法都只取决于选中了哪些节目。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-15b3148c470f85ea":[["国考 2023 地市级 行测#63"],["国考 2024 副省级 行测#68","国考 2024 地市级 行测#64"],["国考 2024 行政执法 行测#70"],["江苏 2024 C类 行测#59"]]}};
